Permutations.code:
static void permutations(int[] arr, int index) {
    if (index == arr.length) {
        System.out.println(Arrays.toString(arr));
        return;
    }

    for (int i = index; i < arr.length; i++) {
        swap(arr, index, i);
        permutations(arr, index + 1);
        swap(arr, index, i);
    }
}

static void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

Combination Sum.code:
static void combinationSum(
        int[] candidates,
        int index,
        int target,
        List<Integer> current) {

    if (target == 0) {
        System.out.println(current);
        return;
    }

    if (target < 0 || index == candidates.length) {
        return;
    }

    current.add(candidates[index]);
    combinationSum(candidates, index, target - candidates[index], current);

    current.remove(current.size() - 1);
    combinationSum(candidates, index + 1, target, current);
}

N Queens.code:
static boolean solveNQueens(
        int[][] board,
        int row) {

    int n = board.length;

    if (row == n) {
        return true;
    }

    for (int col = 0; col < n; col++) {
        if (isSafe(board, row, col)) {
            board[row][col] = 1;

            if (solveNQueens(board, row + 1)) {
                return true;
            }

            board[row][col] = 0;
        }
    }

    return false;
}

static boolean isSafe(int[][] board, int row, int col) {
    int n = board.length;

    for (int i = 0; i < row; i++) {
        if (board[i][col] == 1) {
            return false;
        }
    }

    for (int i = row - 1, j = col - 1; i >= 0 && j >= 0; i--, j--) {
        if (board[i][j] == 1) {
            return false;
        }
    }

    for (int i = row - 1, j = col + 1; i >= 0 && j < n; i--, j++) {
        if (board[i][j] == 1) {
            return false;
        }
    }

    return true;
}

Maze Backtracking.code:
static boolean solveMaze(
        int[][] maze,
        int row,
        int col,
        boolean[][] visited) {

    int n = maze.length;
    int m = maze[0].length;

    if (row < 0 || row >= n || col < 0 || col >= m) {
        return false;
    }

    if (maze[row][col] == 0 || visited[row][col]) {
        return false;
    }

    if (row == n - 1 && col == m - 1) {
        return true;
    }

    visited[row][col] = true;

    if (solveMaze(maze, row + 1, col, visited) ||
        solveMaze(maze, row - 1, col, visited) ||
        solveMaze(maze, row, col + 1, visited) ||
        solveMaze(maze, row, col - 1, visited)) {
        return true;
    }

    return false;
}
